import{_ as t,o as a,c as n,a5 as s}from"./chunks/framework.DrDMl0tG.js";const r="/assets/length_constraints_newtons_cradle.h6kSVmW3.png",m=JSON.parse(`{"title":"Server Example: Length Constraints Newton's Cradle","description":"","frontmatter":{},"headers":[],"relativePath":"sections/examples/server/length_constraints_newtons_cradle.md","filePath":"sections/examples/server/length_constraints_newtons_cradle.md"}`),o={name:"sections/examples/server/length_constraints_newtons_cradle.md"};function l(i,e,d,c,h,p){return a(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="server-example-length-constraints-newton-s-cradle" tabindex="-1">Server Example: Length Constraints Newton&#39;s Cradle <a class="header-anchor" href="#server-example-length-constraints-newton-s-cradle" aria-label="Permalink to &quot;Server Example: Length Constraints Newton&#39;s Cradle&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Hangs a Newton&#39;s cradle from spatial tendons, attaches a box and two ANYmal robots with spring and tension-driven tendons, and exports the world to XML. Despite the target name, the example uses the tendon API (<code>World::addSpatialTendon</code>); the older wire API now wraps tendons. See <a href="./../../Tendons.html">Tendons</a>.</p><h2 id="screenshot" tabindex="-1">Screenshot <a class="header-anchor" href="#screenshot" aria-label="Permalink to &quot;Screenshot&quot;">​</a></h2><p><img src="'+r+'" alt="length_constraints_newtons_cradle example"></p><h2 id="target" tabindex="-1">Target <a class="header-anchor" href="#target" aria-label="Permalink to &quot;Target&quot;">​</a></h2><p>CMake target: <code>length_constraints_newtons_cradle</code>.</p><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><p>Run the build-tree executable:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build-examples/examples/length_constraints_newtons_cradle</span></span></code></pre></div><p>On Windows, run <code>length_constraints_newtons_cradle.exe</code> instead. This example uses RaisimServer. Start <code>rayrai_tcp_viewer</code> and connect to port 8080.</p><h2 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h2><ul><li>Hangs four steel balls from static pins with cable tendons that have a 2 m upper length limit; the first cable is drawn wider and in red. The last ball starts pulled out to the side.</li><li>Hangs a box and an ANYmal C from spring tendons (stiffness 200 and 1000).</li><li>Lifts an ANYmal B with a tendon driven by <code>Tendon::setTension</code> and removes that tendon with <code>World::removeTendon</code> after 5000 loop iterations.</li><li>Exports the world to <code>exportedWorld.xml</code> next to the executable.</li><li>Integrates only while a viewer is connected.</li></ul>',13)])])}const u=t(o,[["render",l]]);export{m as __pageData,u as default};
